            TodoFilter::Backlog => "backlog",
            TodoFilter::Draft => "draft",
            TodoFilter::Completed => "completed",
            TodoFilter::NotDone => "not_done",
        }
    }

    fn next(self) -> TodoFilter {
        let i = ALL_TODO_FILTERS
            .iter()
            .position(|f| *f == self)
            .unwrap_or(0);
        ALL_TODO_FILTERS[(i + 1) % ALL_TODO_FILTERS.len()]
    }

