// Key and Mouse are the only events that carry local user intent to
// change the view. Snapshot the presentation fields around the
// handler and, if they moved, publish the new view so the other
// clients' same-mode instances adopt it (todo #116). Timer and
// PaneUpdate ticks deliberately do NOT persist - they re-clamp
// cursor/scroll against a changed list identically on every client,
// which is not a user action and must not race the shared seq.
Event::Key(key) => {
    let before = self.view_fingerprint();
    let handled = self.handle_key(key);
    if self.view_fingerprint() != before {
        self.bump_and_persist_view();
