/// Recompute whether this Todos instance is the cockpit gatekeeper leader
/// from the connected-client list (todo #116). The leader is the instance
/// whose client is the lowest-numbered one attached; client ids are stable
/// and monotonic per attach, so the choice is deterministic and shifts to
/// the next-lowest client the moment the leader's client detaches. If our
/// own client is not (yet) in the list, leave leadership unchanged rather
/// than abdicating - dropping to non-leader on a transient empty reply
/// would silently swallow a spawn.
fn update_gatekeeper_leadership(&mut self, clients: &[ClientInfo]) {
    if self.mode != Mode::Todos {
        return;
    }
    let Some(me) = clients.iter().find(|c| c.is_current_client) else {
        return;
    };
    let lowest = clients.iter().map(|c| c.client_id).min();
    self.is_gatekeeper_leader = lowest == Some(me.client_id);
}

