/// The shared content-focus file: which content pane every client mirrors onto
/// (todo #116). One pane id + a monotonic seq, atomically written like the
/// other `.cockpit/` files.
const FOCUS_STATE_PATH: &str = "/host/.panopt/.cockpit/focus.json";

/// Encode a [`PaneId`] for the focus file. Only terminal panes are ever stored
/// (their ids are session-global); the plugin variant is encoded for
/// completeness but plugin-pane focus is not mirrored.
fn encode_pane(pane: PaneId) -> String {
    match pane {
        PaneId::Terminal(id) => format!("t{id}"),
        PaneId::Plugin(id) => format!("p{id}"),
    }
}

fn decode_pane(token: &str) -> Option<PaneId> {
    let (kind, num) = token.split_at(1);
    let id: u32 = num.parse().ok()?;
    match kind {
        "t" => Some(PaneId::Terminal(id)),
        "p" => Some(PaneId::Plugin(id)),
        _ => None,
    }
}

/// Atomically publish the mirrored content focus (temp + rename).
fn write_focus_state(pane: PaneId, seq: u64) {
    let dir = "/host/.panopt/.cockpit";
    if fs::create_dir_all(dir).is_err() {
        return;
    }
    let body = format!("{{\"pane\":\"{}\",\"seq\":{}}}", encode_pane(pane), seq);
    let tmp = format!("{dir}/.focus.tmp");
    if fs::write(&tmp, body).is_ok() {
        let _ = fs::rename(&tmp, FOCUS_STATE_PATH);
    }
}

/// Read the mirrored focus, tolerant of a missing/partial file.
fn read_focus_state() -> Option<(PaneId, u64)> {
    let body = fs::read_to_string(FOCUS_STATE_PATH).ok()?;
    let seq = view_field(&body, "seq")?;
    let needle = "\"pane\":\"";
    let start = body.find(needle)? + needle.len();
    let rest = &body[start..];
    let end = rest.find('"')?;
    let pane = decode_pane(&rest[..end])?;
    Some((pane, seq))
}

