                } else {
                    line.to_string()
                }
            })
            .collect::<Vec<_>>()
            .join("\n");
        return if trailing_nl { out + "\n" } else { out };
    }
    let mut out = base.to_string();
    if !out.ends_with('\n') {
        out.push('\n');
    }
    out.push_str(MIRROR_SESSION_ON);
    out.push('\n');
    out
}

